BEGIN READ ONLY;
SELECT jsonb_build_object(
'columns', (SELECT jsonb_agg(to_jsonb(c)) FROM (SELECT table_name,column_name,data_type,udt_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('releases','products','tracks','catalog_tracks','release_drafts','collaborators','release_collaborators','credit_groups','credit_assignments') ORDER BY table_name,ordinal_position) c),
'constraints', (SELECT jsonb_agg(to_jsonb(c)) FROM (SELECT rel.relname AS table_name,con.conname,con.contype,pg_get_constraintdef(con.oid) AS definition FROM pg_constraint con JOIN pg_class rel ON rel.oid=con.conrelid JOIN pg_namespace n ON n.oid=rel.relnamespace WHERE n.nspname='public' AND rel.relname IN ('releases','products','tracks','catalog_tracks','collaborators','release_collaborators') ORDER BY rel.relname,con.conname) c),
'rls', (SELECT jsonb_agg(to_jsonb(c)) FROM (SELECT c.relname,c.relrowsecurity,c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('releases','products','tracks','catalog_tracks','release_drafts','collaborators','release_collaborators')) c),
'policies', (SELECT jsonb_agg(to_jsonb(p)) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('releases','products','tracks','catalog_tracks','release_drafts','collaborators','release_collaborators')),
'grants', (SELECT jsonb_agg(to_jsonb(g)) FROM information_schema.role_table_grants g WHERE table_schema='public' AND table_name IN ('releases','products','tracks','catalog_tracks','release_drafts','collaborators','release_collaborators')),
'functions', (SELECT jsonb_agg(to_jsonb(f)) FROM (SELECT p.proname,pg_get_function_identity_arguments(p.oid) AS arguments,p.prosecdef,p.proacl,pg_get_functiondef(p.oid) AS definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('commit_current_release_edit','credit_storage_capabilities','get_release_credit_edit_state','commit_release_credit_edit','commit_release_publication')) f),
'migrations', (SELECT jsonb_agg(to_jsonb(m)) FROM (SELECT version,name FROM supabase_migrations.schema_migrations ORDER BY version DESC LIMIT 40) m),
'credit_shapes', (SELECT jsonb_agg(to_jsonb(c)) FROM (SELECT 'products' AS source,jsonb_typeof(to_jsonb(p)->'credits') AS shape,count(*) FROM public.products p GROUP BY 2 UNION ALL SELECT 'catalog_tracks',jsonb_typeof(to_jsonb(t)->'credits'),count(*) FROM public.catalog_tracks t GROUP BY 2) c),
'counts', jsonb_build_object('collaborators',(SELECT count(*) FROM public.collaborators),'release_collaborators',(SELECT count(*) FROM public.release_collaborators),'releases',(SELECT count(*) FROM public.releases),'products',(SELECT count(*) FROM public.products),'tracks',(SELECT count(*) FROM public.tracks),'catalog_tracks',(SELECT count(*) FROM public.catalog_tracks))
) AS inspection;
COMMIT;
